mapper.sql:
s.tenant_id=#{tenantId}


        AND EXISTS(SELECT 1 FROM student_campus_admin ca WHERE ca.tenant_id=s.tenant_id AND ca.user_id=#{userId} AND ca.campus_id=e.campus_id)
        AND (EXISTS(SELECT 1 FROM student_homeroom_assignment ha WHERE ha.tenant_id=s.tenant_id AND ha.user_id=#{userId} AND ha.class_id=e.class_id AND ha.ends_on IS NULL) OR EXISTS(SELECT 1 FROM student_school_class_scope ts WHERE ts.tenant_id=s.tenant_id AND ts.user_id=#{userId} AND ts.class_id=e.class_id))


AND e.academic_year_id=(SELECT id FROM school_academic_year WHERE tenant_id=#{tenantId} AND is_current=1 LIMIT 1)
AND NOT EXISTS(SELECT 1 FROM student_enrollment en2 WHERE en2.tenant_id=e.tenant_id AND en2.student_id=e.student_id AND en2.academic_year_id=e.academic_year_id AND (en2.starts_on>e.starts_on OR (en2.starts_on=e.starts_on AND en2.id>e.id)))
AND e.campus_id=#{campusId}
AND e.academic_year_id=#{academicYearId}
AND e.grade=#{grade}
AND e.class_id=#{classId}
AND e.status=#{status}
AND (s.student_no LIKE CONCAT('%',#{search},'%') OR s.name LIKE CONCAT('%',#{search},'%'))

mapper.select:
SELECT s.id,s.student_no AS studentNo,s.name,s.gender,s.birthday,s.email,s.phone,e.id AS enrollmentId,e.academic_year_id AS academicYearId,y.name AS academicYear,e.campus_id AS campusId,p.name AS campusName,e.grade,e.class_id AS classId,c.class_name AS className,e.status,e.starts_on AS enrolledOn,e.ends_on AS leftOn
 WHERE 
GROUP BY s.id,e.id ORDER BY ${sortColumn} ${sortDirection},s.id LIMIT #{limit} OFFSET #{offset}
